INSERT INTO prompts (id, title, category, role, tags, access, prompt_body) SELECT id, title, 'Banking & Fintech Engagement', 'a senior banking and fintech customer-engagement strategist', tags, access, CONCAT('ROLE: You are a senior banking and fintech customer-engagement strategist with expertise in ', LOWER(tags), '.\n\nTASK: Create a production-ready ', LOWER(title), ' for [specific use-case] and [campaign goal].\n\nAUDIENCE: [target customer segment] with documented consent where required.\n\nPLATFORM / FORMAT: [preferred channel or format].\n\nTONE / VOICE: Clear, reassuring, inclusive, concise, and useful.\n\nPRIMARY GOAL: [campaign goal].\n\nDELIVERABLES:\n1. A ready-to-use sequence, brief, or engagement asset with clear variables.\n2. Personalization logic for [customer segment] and [customer stage].\n3. Timing, CTA, measurement, and human hand-off recommendations.\n4. Channel-specific copy for the tagged channels.\n5. Compliance review notes and an approval checklist.\n\nCONSTRAINTS: Use only consented outreach, minimize personal data, mask identifiers, never request full card numbers, PINs, PANs, or passwords, avoid guaranteed outcomes, include opt-out and HELP handling, use secure authenticated links for sensitive actions, and provide human escalation.') FROM (SELECT '3101' AS id, 'Free WhatsApp opt-in welcome flow' AS title, 'WhatsApp, Banking, Fintech, Free' AS tags, 'FREE' AS access UNION ALL SELECT '3102' AS id, 'Free SMS payment reminder' AS title, 'SMS, Banking, Fintech, Free' AS tags, 'FREE' AS access UNION ALL SELECT '3103' AS id, 'Free KYC checklist explainer' AS title, 'KYC, Banking, Fintech, Free' AS tags, 'FREE' AS access UNION ALL SELECT '3104' AS id, 'Free fraud alert confirmation flow' AS title, 'Fraud, WhatsApp, Banking, Free' AS tags, 'FREE' AS access UNION ALL SELECT '3105' AS id, 'Free financial education short' AS title, 'AI Video, Education, Banking, Free' AS tags, 'FREE' AS access UNION ALL SELECT '3201' AS id, 'Loan application status journey' AS title, 'Lending, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3202' AS id, 'EMI reminder escalation flow' AS title, 'Collections, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3203' AS id, 'KYC document recovery sequence' AS title, 'KYC, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3204' AS id, 'Fraud case human hand-off' AS title, 'Fraud, WhatsApp, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3205' AS id, 'Credit card onboarding campaign' AS title, 'Onboarding, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3206' AS id, 'Salary account activation plan' AS title, 'Onboarding, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3207' AS id, 'Savings goal education series' AS title, 'Education, AI Video, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3208' AS id, 'Personal loan cross-sell journey' AS title, 'Cross-sell, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3209' AS id, 'Dormant account reactivation flow' AS title, 'Retention, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3210' AS id, 'Customer consent audit brief' AS title, 'Compliance, Automation, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3211' AS id, 'Secure link CTA message pack' AS title, 'WhatsApp, Security, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3212' AS id, 'Opt-out and HELP response library' AS title, 'Compliance, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3213' AS id, 'WhatsApp template approval brief' AS title, 'WhatsApp, Compliance, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3214' AS id, 'Interactive button menu design' AS title, 'WhatsApp, Automation, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3215' AS id, 'Chatbot intent and fallback map' AS title, 'Chatbot, Automation, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3216' AS id, 'Agent escalation playbook' AS title, 'Customer Service, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3217' AS id, 'Mobile app download campaign' AS title, 'Acquisition, SMS, Fintech' AS tags, 'LOCKED' AS access) AS batch ON DUPLICATE KEY UPDATE title=VALUES(title), category=VALUES(category), role=VALUES(role), tags=VALUES(tags), access=VALUES(access), prompt_body=VALUES(prompt_body);\n